106	static int hosted_sdio_set_blocksize(struct sdio_dev_s *dev, uint8_t fn,
107	                                     uint16_t size)
108	{
109	    uint8_t lo = size & 0xff;
110	    uint8_t hi = (size >> 8) & 0xff;
111	    uint16_t offset = SD_IO_FBR_START * fn;
112	    int ret;
113	
114	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0,
115	                         offset + SD_IO_CCCR_BLKSIZEL, &lo, 1);
116	    if (ret < 0) {
117	        return ret;
118	    }
119	
120	    ret = SDIO_WRITEFUNC(dev, SDIO_FUNC_0,
121	                         offset + SD_IO_CCCR_BLKSIZEH, &hi, 1);
122	    if (ret < 0) {
123	        return ret;
124	    }
125	
126	    return 0;
127	}
